-- New Tinkertown: rebuild the Target Acquisition Device (46012) spawns.
--
-- Replaces the 53 existing spawns with the 13 real posts. The old set held each
-- post two or three times over, which is what made the area look crowded.
--
-- They hold position; movement is left to the script. Needs a worldserver restart.
DELETE FROM `creature` WHERE `guid` IN (
 168910,168912,168919,168920,168921,168924,168927,168929,168930,168933,
 168934,168935,168938,168942,168943,168944,168945,169235,169236,169237,
 169238,169243,169245,169247,169248,169249,169250,169251,169264,169271,
 169274,169275,169285,169305,169306,169307,169308,169310,169311,169313,
 169314,169316,169320,169321,169322,169323,169328,169329,169331,169332,
 169333,169335,169336);

DELETE FROM `creature` WHERE `guid` BETWEEN 984750 AND 984762;

